package claudecode

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// GenerateTextStreaming runs the Claude CLI in stream-json mode, dispatches
// progress events to the optional callback, and returns the final result text.
// Implements the agent.StreamingTextGenerator interface.
//
// If the CLI rejects the stream-json flags (older Claude CLI), this falls back
// to the non-streaming GenerateText path — without progress events.
func (c *ClaudeCodeAgent) GenerateTextStreaming(
	ctx context.Context,
	prompt, model string,
	progress agent.ProgressFn,
) (string, error) {
	if model == "" {
		model = "haiku"
	}

	commandRunner := c.CommandRunner
	if commandRunner == nil {
		commandRunner = exec.CommandContext
	}

	cmd := commandRunner(ctx, "claude",
		"--print",
		"--output-format", "stream-json",
		"--verbose",
		"--model", model,
		"--setting-sources", "")

	cmd.Dir = os.TempDir()
	cmd.Env = agent.StripGitEnv(os.Environ())
	cmd.Stdin = strings.NewReader(prompt)

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("claude stream stdout pipe: %w", err)
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr

	if err := cmd.Start(); err != nil {
		return "", fmt.Errorf("claude stream start: %w", err)
	}

	final, malformed, parseErr := streamClaudeResponse(stdout, makeProgressDispatcher(progress))
	// Drain any unread stdout so the subprocess can exit cleanly even if the
	// scanner aborted early (e.g. bufio.ErrTooLong on an oversized line).
	// Without this, a blocked pipe would deadlock cmd.Wait() in interactive
	// mode, which has no deadline. The copy error is intentionally discarded —
	// stdout is about to be closed anyway.
	if _, drainErr := io.Copy(io.Discard, stdout); drainErr != nil {
		logging.Debug(ctx, "draining claude stream stdout", slog.String("error", drainErr.Error()))
	}
	waitErr := cmd.Wait()

	if malformed > 0 {
		logging.Warn(ctx, "skipped malformed claude stream lines",
			slog.Int("count", malformed))
	}

	// A specific envelope error outranks a generic ctx-cancel message: if
	// the stream produced an is_error result just before cancellation, the
	// user deserves the specific cause (auth, rate-limit, etc.) rather than
	// "canceled".
	if final != nil && final.IsError {
		return "", envelopeErrorMessage(final)
	}

	// Context errors pass through as sentinels so callers can use errors.Is.
	if ctx.Err() != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		return "", context.Canceled
	}

	if final != nil {
		if final.Result == nil {
			return "", errors.New("claude returned empty result")
		}
		if progress != nil {
			progress(agent.GenerationProgress{
				Phase:        agent.PhaseDone,
				OutputTokens: outputTokensFromUsage(final.Usage),
				DurationMs:   final.DurationMs,
			})
		}
		return *final.Result, nil
	}

	// No envelope: check if the CLI rejected streaming flags (older version).
	// If so, fall back to the non-streaming path.
	if waitErr != nil {
		stderrStr := stderr.String()
		if looksLikeUnrecognizedFlag(stderrStr) {
			logging.Warn(ctx, "claude CLI rejected stream-json flags; falling back to non-streaming (no progress output)",
				slog.String("stderr", strings.TrimSpace(stderrStr)))
			return c.GenerateText(ctx, prompt, model)
		}
		if stderrStr != "" {
			return "", fmt.Errorf("claude stream failed: %s: %w", strings.TrimSpace(stderrStr), waitErr)
		}
		return "", fmt.Errorf("claude stream failed: %w", waitErr)
	}

	if parseErr != nil {
		return "", fmt.Errorf("claude stream parse: %w", parseErr)
	}
	return "", errors.New("claude exited without producing a result")
}

// envelopeErrorMessage formats an is_error result envelope as a user-facing
// error. Preserves the CLI's result text and HTTP status when present.
func envelopeErrorMessage(final *streamEvent) error {
	msg := "claude CLI reported error"
	if final.Result != nil && *final.Result != "" {
		msg = fmt.Sprintf("%s: %s", msg, *final.Result)
	}
	if final.APIErrorStatus != nil {
		msg = fmt.Sprintf("%s (HTTP %d)", msg, *final.APIErrorStatus)
	}
	return errors.New(msg)
}

// makeProgressDispatcher returns a per-event handler that translates raw
// stream events into agent.GenerationProgress callbacks. PhaseDone is
// emitted by GenerateTextStreaming after cmd.Wait, because it needs data
// from the parsed final envelope (OutputTokens, DurationMs).
func makeProgressDispatcher(progress agent.ProgressFn) func(streamEvent) {
	if progress == nil {
		return func(streamEvent) {} // progress disabled; scanner itself reads the stream
	}
	var outputTokensEstimate int
	return func(ev streamEvent) {
		switch {
		case ev.Type == "system" && ev.Subtype == "status" && ev.Status == "requesting":
			progress(agent.GenerationProgress{Phase: agent.PhaseConnecting})
		case ev.Type == "stream_event" && ev.Event.Type == "message_start":
			p := agent.GenerationProgress{Phase: agent.PhaseFirstToken, TTFTms: ev.TTFTms}
			if ev.Event.Message != nil && ev.Event.Message.Usage != nil {
				p.InputTokens = ev.Event.Message.Usage.InputTokens
				p.CachedInputTokens = ev.Event.Message.Usage.CacheReadInputTokens
			}
			progress(p)
		case ev.Type == "stream_event" && ev.Event.Type == "content_block_delta" && ev.Event.Delta != nil:
			text := ev.Event.Delta.Text
			if text == "" {
				text = ev.Event.Delta.Thinking
			}
			outputTokensEstimate += len(text) / 4 // rough estimate: ~4 chars/token
			progress(agent.GenerationProgress{Phase: agent.PhaseGenerating, OutputTokens: outputTokensEstimate})
		}
	}
}

func outputTokensFromUsage(u *messageUsage) int {
	if u == nil {
		return 0
	}
	return u.OutputTokens
}

// looksLikeUnrecognizedFlag returns true if stderr indicates the CLI
// rejected one of the streaming-specific flags (older Claude CLI that
// doesn't support stream-json or --verbose). Requires both a rejection
// phrase AND a streaming flag name to avoid false-positives on unrelated
// errors that happen to contain "unknown option".
func looksLikeUnrecognizedFlag(stderr string) bool {
	lower := strings.ToLower(stderr)
	hasRejectPhrase := strings.Contains(lower, "unrecognized option") ||
		strings.Contains(lower, "unknown flag") ||
		strings.Contains(lower, "unknown option") ||
		strings.Contains(lower, "invalid option")
	if !hasRejectPhrase {
		return false
	}
	return strings.Contains(lower, "stream-json") ||
		strings.Contains(lower, "verbose") ||
		strings.Contains(lower, "include-partial")
}

package claudecode

import (
	"fmt"
	"strings"
)

// ClaudeErrorKind classifies a typed Claude CLI error so callers can
// produce actionable user-facing messages without parsing strings.
type ClaudeErrorKind string

const (
	// ClaudeErrorAuth indicates an authentication or authorization failure
	// (HTTP 401/403 in the CLI envelope, or recognized stderr substring).
	ClaudeErrorAuth ClaudeErrorKind = "auth"
	// ClaudeErrorRateLimit indicates the request was rejected for rate-limit
	// or quota reasons (HTTP 429).
	ClaudeErrorRateLimit ClaudeErrorKind = "rate_limit"
	// ClaudeErrorConfig indicates a client-side request error other than
	// auth or rate-limit (e.g., HTTP 4xx for invalid model or malformed args).
	ClaudeErrorConfig ClaudeErrorKind = "config"
	// ClaudeErrorCLIMissing indicates the claude binary was not found on PATH.
	ClaudeErrorCLIMissing ClaudeErrorKind = "cli_missing"
	// ClaudeErrorUnknown is the catch-all for failures we cannot classify.
	ClaudeErrorUnknown ClaudeErrorKind = "unknown"
)

// ClaudeError is a typed error returned by ClaudeCodeAgent's text generation
// methods. APIStatus and ExitCode use zero to mean "not applicable."
type ClaudeError struct {
	Kind      ClaudeErrorKind
	Message   string // user-safe text extracted from the CLI envelope or stderr
	APIStatus int
	ExitCode  int
	Cause     error
}

func (e *ClaudeError) Error() string {
	if e.Message == "" {
		if e.ExitCode != 0 {
			return fmt.Sprintf("claude CLI error (kind=%s, exit=%d)", e.Kind, e.ExitCode)
		}
		return fmt.Sprintf("claude CLI error (kind=%s)", e.Kind)
	}
	return fmt.Sprintf("claude CLI error (kind=%s): %s", e.Kind, e.Message)
}

func (e *ClaudeError) Unwrap() error { return e.Cause }

const stderrMessageMaxLen = 500

// authStderrPhrases is intentionally small. The primary auth-detection path
// is the structured envelope (classifyEnvelopeError); these phrases are a
// best-effort fallback for crashes that exit non-zero before the envelope
// is produced.
var authStderrPhrases = []string{
	"invalid api key",
	"not logged in",
}

// classifyEnvelopeError converts a Claude CLI is_error:true envelope into a
// typed ClaudeError. The result text is treated as user-safe (the CLI
// produces it for human consumption).
func classifyEnvelopeError(resultText string, apiStatus *int, exitCode int) *ClaudeError {
	e := &ClaudeError{
		Message:  resultText,
		ExitCode: exitCode,
	}
	if apiStatus != nil {
		e.APIStatus = *apiStatus
	}
	switch {
	case e.APIStatus == 401, e.APIStatus == 403:
		e.Kind = ClaudeErrorAuth
	case e.APIStatus == 429:
		e.Kind = ClaudeErrorRateLimit
	case e.APIStatus >= 400 && e.APIStatus < 500:
		e.Kind = ClaudeErrorConfig
	case e.APIStatus == 0 && hasAuthPhrase(resultText):
		// No structured status (older CLI builds / internal errors) — fall
		// back to the same phrase heuristic the stderr path uses so users
		// still get auth-specific guidance.
		e.Kind = ClaudeErrorAuth
	default:
		e.Kind = ClaudeErrorUnknown
	}
	return e
}

// classifyStderrError is a fallback classifier used when the subprocess exited
// non-zero without producing a parseable envelope. It only attempts to
// recognize a small, stable set of auth phrases; everything else becomes
// ClaudeErrorUnknown with the (truncated) stderr as the message.
func classifyStderrError(stderr string, exitCode int) *ClaudeError {
	msg := strings.TrimSpace(stderr)
	if len(msg) > stderrMessageMaxLen {
		msg = msg[:stderrMessageMaxLen]
	}
	e := &ClaudeError{Message: msg, ExitCode: exitCode}
	if hasAuthPhrase(msg) {
		e.Kind = ClaudeErrorAuth
		return e
	}
	e.Kind = ClaudeErrorUnknown
	return e
}

func hasAuthPhrase(s string) bool {
	lower := strings.ToLower(s)
	for _, phrase := range authStderrPhrases {
		if strings.Contains(lower, phrase) {
			return true
		}
	}
	return false
}

