// from Claude CLI JSON output. Claude may return either a single object or an array of events.
// The returned envelope allows callers to check IsError and APIErrorStatus.
func parseGenerateTextResponse(stdout []byte) (string, *responseEnvelope, error) {
	var response responseEnvelope
	if err := json.Unmarshal(stdout, &response); err == nil {
		if response.Result != nil {
			return *response.Result, &response, nil
		}
		// is_error:true with null result is a structured CLI failure; callers
		// need the envelope (IsError, APIErrorStatus) for classification.
		if response.IsError {
			return "", &response, nil
		}
	}

	var responses []responseEnvelope
	if err := json.Unmarshal(stdout, &responses); err != nil {
		return "", nil, fmt.Errorf("unsupported Claude CLI JSON response: %w", err)
	}

	for i := len(responses) - 1; i >= 0; i-- {
		if responses[i].Type != "result" {
			continue
		}
		if responses[i].Result != nil {
			return *responses[i].Result, &responses[i], nil
		}
		// Mirror the object-path behavior: is_error:true with null result is
		// a structured failure whose envelope (IsError, APIErrorStatus) must
		// reach classifyEnvelopeError.
		if responses[i].IsError {
			return "", &responses[i], nil
		}
	}

	return "", nil, errors.New("unsupported Claude CLI JSON response: missing result item")
}

// streamBufferMax bounds a single NDJSON line. Stream events can be large
// (init carries the full tool list; deltas can carry long thinking chunks)
// so we lift the default scanner limit substantially.
const streamBufferMax = 4 * 1024 * 1024 // 4 MiB

// streamEvent represents one decoded line from the stream-json NDJSON output.
// Fields are populated based on the event Type/Subtype.
type streamEvent struct {
	Type    string           `json:"type"`
	Subtype string           `json:"subtype"`
	Status  string           `json:"status"` // e.g. "requesting" for type=system,subtype=status
	Event   streamInnerEvent `json:"event"`  // for type=stream_event

	// Fields populated for type=result.
	IsError        bool          `json:"is_error"`
	APIErrorStatus *int          `json:"api_error_status"`
	Result         *string       `json:"result"`
	DurationMs     int           `json:"duration_ms"`
	TTFTms         int           `json:"ttft_ms,omitempty"` // time-to-first-token; on outer stream_event envelope
	Usage          *messageUsage `json:"usage"`
}

// streamInnerEvent holds the nested "event" payload for type=stream_event.
type streamInnerEvent struct {
	Type    string         `json:"type"` // "message_start" | "content_block_delta" | "message_delta" | ...
	Delta   *streamDelta   `json:"delta,omitempty"`
	Message *streamMessage `json:"message,omitempty"`
}

// streamDelta carries the content-block delta payload.
type streamDelta struct {
	Type     string `json:"type"` // "text_delta" | "thinking_delta" | ...
	Text     string `json:"text,omitempty"`
	Thinking string `json:"thinking,omitempty"`
}

// streamMessage is the partial-message payload on message_start. Only the
// usage field is currently consumed by callers; other fields are ignored.
type streamMessage struct {
	Usage *messageUsage `json:"usage,omitempty"`
}

// streamClaudeResponse reads NDJSON-encoded events from r, invokes onEvent
// for every successfully decoded event, and returns the final result event
// once the stream ends. Malformed lines are skipped to keep the stream
// resilient against single-line corruption; the count is returned so callers
// can log schema drift even on otherwise-successful runs.
func streamClaudeResponse(r io.Reader, onEvent func(streamEvent)) (*streamEvent, int, error) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 64*1024), streamBufferMax)
	var final *streamEvent
	var malformedLines int
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var ev streamEvent
		if err := json.Unmarshal(line, &ev); err != nil {
			malformedLines++
			continue // best-effort: skip and keep streaming
		}
		if onEvent != nil {
			onEvent(ev)
		}
		if ev.Type == "result" {
			captured := ev
			final = &captured
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, malformedLines, fmt.Errorf("reading claude stream: %w", err)
	}
	if final == nil {
		if malformedLines > 0 {
			return nil, malformedLines, fmt.Errorf("claude stream ended without a result event (%d malformed lines skipped)", malformedLines)
		}
		return nil, 0, errors.New("claude stream ended without a result event")
	}
	return final, malformedLines, nil
}

package claudecode

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText sends a prompt to the Claude CLI and returns the raw text response.
// Implements the agent.TextGenerator interface.
// The model parameter hints which model to use (e.g., "haiku", "sonnet").
// If empty, defaults to "haiku" for fast, cheap generation.
//
// Unlike most agents, this implementation runs the subprocess directly rather
// than through agent.RunIsolatedTextGeneratorCLI. The shared helper collapses
// stderr + exit code into a single formatted error string, but Claude CLI
// returns operational errors (auth, rate limit, invalid model) as exit 0
// with is_error:true in the JSON envelope on stdout — so we need structured
// access to stdout, stderr and the exit code to produce the typed ClaudeError
// values that formatCheckpointSummaryError maps to actionable messages.
func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
	claudePath := "claude"
	if model == "" {
		model = "haiku"
	}

	commandRunner := c.CommandRunner
	if commandRunner == nil {
		commandRunner = exec.CommandContext
	}

	cmd := commandRunner(ctx, claudePath,
		"--print", "--output-format", "json",
		"--model", model, "--setting-sources", "")

	// Isolate from the user's git repo to prevent recursive hook triggers
	// and index pollution (matches agent.RunIsolatedTextGeneratorCLI behavior).
	cmd.Dir = os.TempDir()
	cmd.Env = agent.StripGitEnv(os.Environ())
	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		// Prefer a structured Claude error over bare ctx sentinels: if the CLI
		// already emitted an is_error envelope on stdout, surface that even when
		// the context happens to be done. Otherwise the user loses actionable
		// auth/rate-limit/config diagnostics whenever ctx and the subprocess
		// both fail at roughly the same time.
		if _, env, parseErr := parseGenerateTextResponse(stdout.Bytes()); parseErr == nil && env != nil && env.IsError {
			result := ""
			if env.Result != nil {
				result = *env.Result
			}
			exitCode := 0
			var exitErr *exec.ExitError
			if errors.As(err, &exitErr) {
				exitCode = exitErr.ExitCode()
			}
			return "", classifyEnvelopeError(result, env.APIErrorStatus, exitCode)
		}
		// No structured signal on stdout — ctx cancellation is next most
		// informative, since the rest is a guess.
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		if isExecNotFound(err) {
			return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
		}
		exitCode := -1
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		}
		return "", classifyStderrError(stderr.String(), exitCode)
	}

	// Exit 0: parse the response and check for is_error (Claude CLI returns
	// most operational errors as exit 0 with is_error:true in the envelope).
	result, env, err := parseGenerateTextResponse(stdout.Bytes())
	if err != nil {
		return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: fmt.Sprintf("failed to parse claude CLI response: %v", err), Cause: err}
	}
	if env != nil && env.IsError {
		return "", classifyEnvelopeError(result, env.APIErrorStatus, 0)
	}

	return result, nil
}

// isExecNotFound returns true only when err indicates the binary was not
// found on PATH or at the given absolute path. It intentionally excludes
// other *exec.Error causes (permission denied, invalid executable format),
// which should surface as a generic failure so operators aren't misdirected
// to a reinstall when the real problem is a broken/inaccessible binary.
func isExecNotFound(err error) bool {
	var execErr *exec.Error
	if errors.As(err, &execErr) && errors.Is(execErr.Err, exec.ErrNotFound) {
		return true
	}
	return errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist)
}

