// Package summarize provides AI-powered summarization of development sessions.
package summarize

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/factoryaidroid"
	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
	"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
	"github.com/entireio/cli/cmd/entire/cli/transcript/compact"
	"github.com/entireio/cli/redact"
)

// GenerateFromTranscript generates a summary from pre-redacted transcript bytes.
// This is the shared implementation used by both explain --generate and auto-summarize.
//
// Parameters:
//   - ctx: context for cancellation
//   - transcriptBytes: pre-redacted transcript (JSONL or JSON format depending on agent)
//   - filesTouched: list of files modified during the session
//   - agentType: the agent type to determine transcript format
//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
//   - progress: optional callback for streaming progress events (nil to suppress)
//
// Returns nil, error if transcript is empty or cannot be parsed.
func GenerateFromTranscript(ctx context.Context, transcriptBytes redact.RedactedBytes, filesTouched []string, agentType types.AgentType, generator Generator, progress agent.ProgressFn) (*checkpoint.Summary, error) {
	if transcriptBytes.Len() == 0 {
		return nil, errors.New("empty transcript")
	}

	// Build condensed transcript for summarization
	condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}
	if len(condensed) == 0 {
		return nil, errors.New("transcript has no content to summarize")
	}

	input := Input{
		Transcript:   condensed,
		FilesTouched: filesTouched,
	}

	if generator == nil {
		generator = &ClaudeGenerator{Progress: progress}
	} else if cg, ok := generator.(*ClaudeGenerator); ok && cg.Progress == nil && progress != nil {
		// Clone to avoid mutating the caller's struct.
		clone := *cg
		clone.Progress = progress
		generator = &clone
	}

	summary, err := generator.Generate(ctx, input)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve *ClaudeError for errors.As at the explain layer
	}

	return summary, nil
}

// Generator generates checkpoint summaries using an LLM.
type Generator interface {
	// Generate creates a summary from checkpoint data.
	// Returns the generated summary or an error if generation fails.
	Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
}

// ResolveModel returns the effective model to use for summary generation.
// When the provider is Claude Code and no model is configured, it falls back
// to DefaultModel ("sonnet") — the summarize package's quality/cost choice,
// which differs from Claude Code's own invocation default ("haiku"). For
// other providers, an empty model means "use the provider CLI's own default",
// so we leave it unchanged.
func ResolveModel(name types.AgentName, model string) string {
	if name == agent.AgentNameClaudeCode && model == "" {
		return DefaultModel
	}
	return model
}

// Input contains condensed checkpoint data for summarization.
type Input struct {
	// Transcript is the condensed transcript entries
	Transcript []Entry

	// FilesTouched are the files modified during the session
	FilesTouched []string
}

// EntryType represents the type of a transcript entry.
type EntryType string

const (
	// EntryTypeUser indicates a user prompt entry.
	EntryTypeUser EntryType = "user"
	// EntryTypeAssistant indicates an assistant response entry.
	EntryTypeAssistant EntryType = "assistant"
	// EntryTypeTool indicates a tool call entry.
	EntryTypeTool EntryType = "tool"
)

// Entry represents one item in the condensed transcript.
type Entry struct {
	// Type is the entry type (user, assistant, tool)
	Type EntryType

	// Content is the text content for user/assistant entries
	Content string

	// ToolName is the name of the tool (for tool entries)
	ToolName string

	// ToolDetail is a description or file path (for tool entries)
	ToolDetail string
}

// minimalDetailTools lists tools that should show only essential details in summaries.
// These tools often have verbose outputs that don't add value to summarization.
// The detail shown is typically just a path, URL, or identifier rather than full content.
var minimalDetailTools = map[string]bool{
	"Skill":    true, // Show skill name only, not loaded content
	"Read":     true, // Show file path only, not file contents
	"WebFetch": true, // Show URL only, not fetched content
}

// BuildCondensedTranscriptFromBytes parses pre-redacted transcript bytes and extracts a condensed view.
// This is a convenience function that combines parsing and condensing.
// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
func BuildCondensedTranscriptFromBytes(content redact.RedactedBytes, agentType types.AgentType) ([]Entry, error) {
	switch agentType {
	case agent.AgentTypeGemini:
		return buildCondensedTranscriptFromGemini(content)
	case agent.AgentTypeFactoryAIDroid:
		return buildCondensedTranscriptFromDroid(content)
	case agent.AgentTypeOpenCode:
		return buildCondensedTranscriptFromOpenCode(content)
	case agent.AgentTypeCodex:
		return buildCondensedTranscriptFromCodex(content)
	case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
		// Claude/cursor format - fall through to shared logic below
	}
	// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
	lines, err := transcript.ParseFromBytes(content.Bytes())
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}
	return BuildCondensedTranscript(lines), nil
}

// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
func buildCondensedTranscriptFromGemini(redacted redact.RedactedBytes) ([]Entry, error) {
	geminiTranscript, err := geminicli.ParseTranscript(redacted.Bytes())
	if err != nil {
		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
	}

	var entries []Entry
	for _, msg := range geminiTranscript.Messages {
		switch msg.Type {
		case geminicli.MessageTypeUser:
			if msg.Content != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeUser,
					Content: msg.Content,
				})
			}
		case geminicli.MessageTypeGemini:
			// Add assistant content
			if msg.Content != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeAssistant,
					Content: msg.Content,
				})
			}
			// Add tool calls
			for _, tc := range msg.ToolCalls {
				entries = append(entries, Entry{
					Type:       EntryTypeTool,
					ToolName:   tc.Name,
					ToolDetail: extractGenericToolDetail(tc.Args),
				})
			}
		}
	}

	return entries, nil
}

// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
func buildCondensedTranscriptFromOpenCode(redacted redact.RedactedBytes) ([]Entry, error) {
	session, err := opencode.ParseExportSession(redacted.Bytes())
	if err != nil {
		return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
	}
	if session == nil {
		return nil, nil
	}

	var entries []Entry
	for _, msg := range session.Messages {
		switch msg.Info.Role {
		case "user":
			text := opencode.ExtractTextFromParts(msg.Parts)
			if text != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeUser,
					Content: text,
				})
			}
		case "assistant":
			text := opencode.ExtractTextFromParts(msg.Parts)
			if text != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeAssistant,
					Content: text,
				})
			}
			for _, part := range msg.Parts {
				if part.Type == "tool" && part.State != nil {
					entries = append(entries, Entry{
						Type:       EntryTypeTool,
						ToolName:   part.Tool,
						ToolDetail: extractOpenCodeToolDetail(part.State.Input),
					})
				}
			}
		}
	}

	return entries, nil
}

// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
// transcript format, then reuses the shared transcript condensation logic.
func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
	compacted, err := compact.Compact(content, compact.MetadataFields{
		Agent:      "codex",
		CLIVersion: "summarize",
	})
	if err != nil {
		return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
	}

	type compactUserTextBlock struct {
		Text string `json:"text"`
	}
	type compactAssistantBlock struct {
		Type  string          `json:"type"`
		Text  string          `json:"text,omitempty"`
		Name  string          `json:"name,omitempty"`
		Input json.RawMessage `json:"input,omitempty"`
	}
	type compactLine struct {
		Type    string          `json:"type"`
		Content json.RawMessage `json:"content"`
	}

	var entries []Entry
	for _, lineBytes := range splitCompactJSONL(compacted) {
		var line compactLine
		if err := json.Unmarshal(lineBytes, &line); err != nil {
			continue
		}

		switch line.Type {
		case transcript.TypeUser:
			var blocks []compactUserTextBlock
			if err := json.Unmarshal(line.Content, &blocks); err != nil {
				continue
			}
			for _, block := range blocks {
				if block.Text != "" {
					entries = append(entries, Entry{
						Type:    EntryTypeUser,
						Content: block.Text,
					})
				}
			}
		case transcript.TypeAssistant:
			var blocks []compactAssistantBlock
			if err := json.Unmarshal(line.Content, &blocks); err != nil {
				continue
			}
			for _, block := range blocks {
				switch block.Type {
				case transcript.ContentTypeText:
					if block.Text != "" {
						entries = append(entries, Entry{
							Type:    EntryTypeAssistant,
							Content: block.Text,
						})
					}
				case transcript.ContentTypeToolUse:
					var input map[string]interface{}
					if err := json.Unmarshal(block.Input, &input); err != nil {
						input = nil
					}
					entries = append(entries, Entry{
						Type:       EntryTypeTool,
						ToolName:   block.Name,
						ToolDetail: extractGenericToolDetail(input),
					})
				}
			}
		}
	}

	return entries, nil
}

// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
func buildCondensedTranscriptFromDroid(redacted redact.RedactedBytes) ([]Entry, error) {
	droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(redacted.Bytes(), 0)
	if err != nil {
		return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
	}
	return BuildCondensedTranscript(droidLines), nil
}

// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
func extractOpenCodeToolDetail(input map[string]interface{}) string {
	for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
		if v, ok := input[key].(string); ok && v != "" {
			return v
		}
	}
	return ""
}

// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
// Checks common fields in order of preference.
func extractGenericToolDetail(input map[string]interface{}) string {
	if input == nil {
		return ""
	}
	for _, key := range []string{"description", "command", "cmd", "file_path", "path", "pattern"} {
		if v, ok := input[key].(string); ok && v != "" {
			return v
		}
	}
	return ""
}

func splitCompactJSONL(data []byte) [][]byte {
	var lines [][]byte
	for _, line := range bytes.Split(data, []byte("\n")) {
		line = bytes.TrimSpace(line)
		if len(line) > 0 {
			lines = append(lines, line)
		}
	}
	return lines
}

// BuildCondensedTranscript extracts a condensed view of the transcript.
// It processes user prompts, assistant responses, and tool calls into
// a simplified format suitable for LLM summarization.
func BuildCondensedTranscript(lines []transcript.Line) []Entry {
	var entries []Entry

	for _, line := range lines {
		switch line.Type {
		case transcript.TypeUser:
			if entry := extractUserEntry(line); entry != nil {
				entries = append(entries, *entry)
			}
		case transcript.TypeAssistant:
			assistantEntries := extractAssistantEntries(line)
			entries = append(entries, assistantEntries...)
		}
	}

	return entries
}

// skillContentPrefix identifies user messages that are skill content injections.
// These are injected after a Skill tool call and contain the full skill instructions.
const skillContentPrefix = "Base directory for this skill:"

// extractUserEntry extracts a user entry from a transcript line.
// Returns nil if the line doesn't contain a valid user prompt or is skill content.
func extractUserEntry(line transcript.Line) *Entry {
	content := transcript.ExtractUserContent(line.Message)
	if content == "" {
		return nil
	}

	// Skip skill content injections - these are verbose skill instructions
	// injected as user messages after Skill tool invocations in Claude Code.
	// The prefix "Base directory for this skill:" is added by the superpowers
	// plugin when loading skill content. This filtering reduces transcript noise
	// since skill content is documentation, not user intent.
	if strings.HasPrefix(content, skillContentPrefix) {
		return nil
	}

	return &Entry{
		Type:    EntryTypeUser,
		Content: content,
	}
}

// extractAssistantEntries extracts assistant and tool entries from a transcript line.
func extractAssistantEntries(line transcript.Line) []Entry {
	var msg transcript.AssistantMessage
	if err := json.Unmarshal(line.Message, &msg); err != nil {
		return nil
	}

	var entries []Entry

	for _, block := range msg.Content {
		switch block.Type {
		case transcript.ContentTypeText:
			if block.Text != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeAssistant,
					Content: block.Text,
				})
			}
		case transcript.ContentTypeToolUse:
			var input transcript.ToolInput
			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing

			detail := extractToolDetail(block.Name, input)

			entries = append(entries, Entry{
				Type:       EntryTypeTool,
				ToolName:   block.Name,
				ToolDetail: detail,
			})
		}
	}

	return entries
}

// extractToolDetail extracts an appropriate detail string for a tool call.
// For tools in minimalDetailTools, only essential identifiers are shown.
// For other tools, the full detail chain is used.
func extractToolDetail(toolName string, input transcript.ToolInput) string {
	// For minimal detail tools, extract only the essential identifier
	if minimalDetailTools[toolName] {
		switch toolName {
		case "Skill":
			return input.Skill
		case "Read":
			if input.FilePath != "" {
				return input.FilePath
			}
			return input.NotebookPath
		case "WebFetch":
			return input.URL
		}
	}

	// For other tools, use the full detail chain
	if input.Description != "" {
		return input.Description
	}
	if input.Command != "" {
		return input.Command
	}
	if input.FilePath != "" {
		return input.FilePath
	}
	if input.NotebookPath != "" {
		return input.NotebookPath
	}
	return input.Pattern
}

// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
// The format is:
//
//	[User] user prompt here
//
//	[Assistant] assistant response here
//
//	[Tool] ToolName: description or file path
func FormatCondensedTranscript(input Input) string {
	var sb strings.Builder

	for i, entry := range input.Transcript {
		if i > 0 {
			sb.WriteString("\n")
		}

		switch entry.Type {
		case EntryTypeUser:
			sb.WriteString("[User] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n")
		case EntryTypeAssistant:
			sb.WriteString("[Assistant] ")
			sb.WriteString(entry.Content)
			sb.WriteString("\n")
		case EntryTypeTool:
			sb.WriteString("[Tool] ")
			sb.WriteString(entry.ToolName)
			if entry.ToolDetail != "" {
				sb.WriteString(": ")
				sb.WriteString(entry.ToolDetail)
			}
			sb.WriteString("\n")
		}
	}

	if len(input.FilesTouched) > 0 {
		sb.WriteString("\n[Files Modified]\n")
		for _, file := range input.FilesTouched {
			fmt.Fprintf(&sb, "- %s\n", file)
		}
	}

	return sb.String()
}

package summarize

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

// summarizationPromptTemplate is the prompt used to generate summaries via the Claude CLI.
//
// Security note: The transcript is wrapped in <transcript> tags to provide clear boundary
// markers. This helps contain any potentially malicious content within the transcript
// (e.g., prompt injection attempts in user messages or file contents) by giving the LLM
// a clear structural signal about where the untrusted content begins and ends.
const summarizationPromptTemplate = `Analyze this development session transcript and generate a structured summary.

<transcript>
%s
</transcript>

Return a JSON object with this exact structure:
{
  "intent": "What the user was trying to accomplish (1-2 sentences)",
  "outcome": "What was actually achieved (1-2 sentences)",
  "learnings": {
    "repo": ["Codebase-specific patterns, conventions, or gotchas discovered"],
    "code": [{"path": "file/path.go", "line": 42, "end_line": 56, "finding": "What was learned"}],
    "workflow": ["General development practices or tool usage insights"]
  },
  "friction": ["Problems, blockers, or annoyances encountered"],
  "open_items": ["Tech debt, unfinished work, or things to revisit later"]
}

Guidelines:
- Be concise but specific
- Include line numbers for code learnings when the transcript references specific lines
- Friction should capture both blockers and minor annoyances
- Open items are things intentionally deferred, not failures
- Empty arrays are fine if a category doesn't apply
- Return ONLY the JSON object, no markdown formatting or explanation`

// DefaultModel is the default model used for summarization.
// Sonnet provides a good balance of quality and cost, with 1M context window
// to handle long transcripts without truncation.
const DefaultModel = "sonnet"

var defaultTextGeneratorFactory = func() (agent.TextGenerator, error) {
	textGenerator, ok := agent.AsTextGenerator(claudecode.NewClaudeCodeAgent())
	if !ok {
		return nil, errors.New("default summarizer does not support text generation")
	}
	return textGenerator, nil
}

// ClaudeGenerator generates summaries using the Claude CLI.
type ClaudeGenerator struct {
	// TextGenerator is the primitive used to obtain raw model output.
	// If nil, uses the built-in Claude Code text generator.
	TextGenerator agent.TextGenerator

	// Model is the Claude model to use for summarization.
	// If empty, defaults to DefaultModel ("sonnet").
	Model string

	// Progress receives streaming progress events when the underlying agent
	// implements agent.StreamingTextGenerator. Optional; nil suppresses reporting.
	Progress agent.ProgressFn
}

// Generate creates a summary from checkpoint data by calling the Claude CLI.
func (g *ClaudeGenerator) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	// Format the transcript for the prompt
	transcriptText := FormatCondensedTranscript(input)

	// Build the prompt
	prompt := buildSummarizationPrompt(transcriptText)

	model := g.Model
	if model == "" {
		model = DefaultModel
	}

	textGenerator := g.TextGenerator
	if textGenerator == nil {
		var err error
		textGenerator, err = defaultTextGeneratorFactory()
		if err != nil {
			return nil, err
		}
	}

	var resultJSON string
	var err error
	if streamer, ok := agent.AsStreamingTextGenerator(textGenerator); ok {
		resultJSON, err = streamer.GenerateTextStreaming(ctx, prompt, model, g.Progress)
	} else {
		resultJSON, err = textGenerator.GenerateText(ctx, prompt, model)
	}
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve *ClaudeError for errors.As at the explain layer
	}

	return parseSummaryText(resultJSON)
}

// buildSummarizationPrompt creates the prompt for the Claude CLI.
func buildSummarizationPrompt(transcriptText string) string {
	return fmt.Sprintf(summarizationPromptTemplate, transcriptText)
}

func parseSummaryText(result string) (*checkpoint.Summary, error) {
	resultJSON := extractJSONFromMarkdown(result)

	var summary checkpoint.Summary
	if err := json.Unmarshal([]byte(resultJSON), &summary); err != nil {
		start := strings.Index(resultJSON, "{")
		end := strings.LastIndex(resultJSON, "}")
		if start >= 0 && end > start {
			candidate := resultJSON[start : end+1]
			if candidate != resultJSON {
				if retryErr := json.Unmarshal([]byte(candidate), &summary); retryErr == nil {
					return &summary, nil
				}
			}
		}
		return nil, fmt.Errorf("failed to parse summary JSON: %w (response: %s)", err, resultJSON)
	}

	return &summary, nil
}

// extractJSONFromMarkdown attempts to extract JSON from markdown code blocks.
// If the input is not wrapped in code blocks, it returns the input unchanged.
func extractJSONFromMarkdown(s string) string {
	s = strings.TrimSpace(s)

	// Check for ```json ... ``` blocks
	if strings.HasPrefix(s, "```json") {
		s = strings.TrimPrefix(s, "```json")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	// Check for ``` ... ``` blocks
	if strings.HasPrefix(s, "```") {
		s = strings.TrimPrefix(s, "```")
		if idx := strings.LastIndex(s, "```"); idx != -1 {
			s = s[:idx]
		}
		return strings.TrimSpace(s)
	}

	return s
}

		}
		return nil, resolved.duration, err
	}

	return summary, resolved.duration, nil
}

// errorsContainsTypedClaudeErr reports whether err's chain carries a typed
// *claudecode.ClaudeError. Used to avoid classifying a real auth/rate-limit
// failure as an idle-watchdog timeout when the watchdog happens to have
// fired while the CLI was already returning a structured error.
func errorsContainsTypedClaudeErr(err error) bool {
	var ce *claudecode.ClaudeError
	return errors.As(err, &ce)
}

// formatCheckpointSummaryError maps typed Claude CLI errors and context
// sentinels to user-facing messages.
func formatCheckpointSummaryError(err error, deadline time.Duration) error {
	var claudeErr *claudecode.ClaudeError
	switch {
	case errors.As(err, &claudeErr):
		switch claudeErr.Kind { //nolint:exhaustive // ClaudeErrorUnknown handled by default
		case claudecode.ClaudeErrorAuth:
			return fmt.Errorf("Claude authentication failed%s\nRun `claude login` and retry", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005: capitalized because Claude is a proper noun
		case claudecode.ClaudeErrorRateLimit:
			return fmt.Errorf("Claude rejected the summary request due to rate limits or quota%s\nWait and retry", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005
		case claudecode.ClaudeErrorConfig:
			return fmt.Errorf("Claude rejected the summary request%s\nCheck your Claude CLI config and selected model", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005
		case claudecode.ClaudeErrorCLIMissing:
			return errors.New("Claude CLI is not installed or not on PATH") //nolint:staticcheck // ST1005
		default:
			return fmt.Errorf("Claude failed to generate the summary%s", formatClaudeErrorSuffix(claudeErr)) //nolint:staticcheck // ST1005
		}
	case errors.Is(err, context.DeadlineExceeded):
		// Deliberately provider-neutral: explain --generate supports multiple
		// summary providers (claude-code, codex, gemini, ...), so hardcoding
		// "Claude" / "sonnet" / "Anthropic" here would misdirect users who
		// selected a different provider in .entire/settings.json.
		return fmt.Errorf(
			"summary generation did not return within the %s safety deadline. This usually means one of:\n"+
				"  - the selected model is taking longer than expected on a large transcript\n"+
				"  - the summary provider's CLI cannot reach its API (network, VPN, firewall)\n"+
				"    Try: run the provider CLI directly to confirm it works\n"+
				"  - the provider's API is degraded",
			formatSummaryTimeout(deadline))
	case errors.Is(err, context.Canceled):
		return errors.New("summary generation canceled")
	default:
		return fmt.Errorf("failed to generate summary: %w", err)
	}
}

// formatMessageSuffix formats ": <msg>" when msg is non-empty and "" otherwise.
// Used by the Auth / RateLimit / Config branches of formatCheckpointSummaryError
// to avoid rendering a bare colon when ClaudeError.Message is empty (reachable
// when the CLI envelope is is_error:true with result:null but a real status).
func formatMessageSuffix(msg string) string {
	if msg == "" {
		return ""
	}
	return ": " + msg
}

// formatClaudeErrorSuffix builds a diagnostic suffix for user-facing output
// when we fall through to the default "failed to generate the summary" path.
// Prefers the envelope Message, falls back to HTTP status, then exit code,
// so the user never sees a bare "Claude failed to generate the summary:"
// with nothing after the colon (which happens when Claude returns
// is_error:true with result:null, or when the subprocess crashes with no
// stderr output). ExitCode < 0 means the subprocess did not produce a real
// exit code (e.g. launch failure) — render that as "abnormal termination"
// rather than the misleading "exited with code -1".
func formatClaudeErrorSuffix(e *claudecode.ClaudeError) string {
	if e.Message != "" {
		return ": " + e.Message
	}
	switch {
	case e.APIStatus != 0:
		return fmt.Sprintf(" (Anthropic API returned HTTP %d)", e.APIStatus)

	case e.ExitCode > 0:
		return fmt.Sprintf(" (claude CLI exited with code %d)", e.ExitCode)
	case e.ExitCode < 0:
		return " (claude CLI terminated abnormally — no exit code captured)"
	default:
		return " (no diagnostic detail available from Claude CLI)"
	}
}

const defaultNonTTYSummaryDeadline = 5 * time.Minute

// maxWallClockSummaryDeadline is the absolute upper bound for summary
// generation, even when the idle watchdog keeps getting refreshed.
// Prevents a degraded but chatty Claude CLI from holding CI jobs open
// indefinitely.
const maxWallClockSummaryDeadline = 30 * time.Minute

// startIdleWatchdog cancels the returned context if more than idle elapses
// between successive updates to *lastActivity. It is a no-op when idle <= 0.
// stop() must be called in a defer to release the goroutine; fired reports
// whether the watchdog was the reason for cancellation.
func startIdleWatchdog(parent context.Context, idle time.Duration, lastActivity *atomic.Int64) (ctx context.Context, fired *atomic.Bool, stop func()) {
	fired = &atomic.Bool{}
	if idle <= 0 {
		return parent, fired, func() {}
	}
	ctx, cancel := context.WithCancel(parent)
	done := make(chan struct{})
	go func() {
		poll := idle / 4
		if poll < time.Millisecond {
			poll = time.Millisecond
		}
		ticker := time.NewTicker(poll)
		defer ticker.Stop()
		for {
			select {
			case <-ticker.C:
				ts := lastActivity.Load()
				if ts > 0 && time.Since(time.Unix(0, ts)) >= idle {
					fired.Store(true)
					cancel()
					return
				}
			case <-done:
				return
			case <-parent.Done():
				return
			}
		}
	}()
	return ctx, fired, func() { close(done); cancel() }
}

// summaryProgressWriter renders agent.GenerationProgress events to the
// configured writer using the existing statusStyles helper. On a TTY (and
// outside ACCESSIBLE mode) it rewrites the current line for the running
// token count; otherwise it appends one line per non-deduplicated event.
type summaryProgressWriter struct {
	w            io.Writer
	inplace      bool
	lastActivity atomic.Int64 // Unix-nano timestamp of last progress event
	lastLine     string
	arrow        string // precomputed styled glyph
	check        string // precomputed styled glyph
}

func newSummaryProgressWriter(w io.Writer) *summaryProgressWriter {
	styles := newStatusStyles(w)
	pw := &summaryProgressWriter{
		w:       w,
		inplace: isTerminalWriter(w) && !IsAccessibleMode(),
		arrow:   styles.render(styles.cyan, "→"),
		check:   styles.render(styles.green, "✓"),
	}
	pw.lastActivity.Store(time.Now().UnixNano())
	return pw
}

func (s *summaryProgressWriter) handle(p agent.GenerationProgress) {
	s.lastActivity.Store(time.Now().UnixNano())
	switch p.Phase {
	case agent.PhaseConnecting:
		s.printLine(s.arrow + " Sending request to Anthropic...")
	case agent.PhaseFirstToken:
		s.printLine(fmt.Sprintf(
			"%s Anthropic responded (TTFT %s, %s cached input tokens) -- generating...",
			s.arrow, formatMs(p.TTFTms), formatTokenCount(p.CachedInputTokens)))
	case agent.PhaseGenerating:
		s.updateLine(fmt.Sprintf(
			"%s Writing summary... (~%s tokens)",
			s.arrow, formatTokenCount(p.OutputTokens)))
	case agent.PhaseMessage:
		// Heartbeat-mode runners forward raw stderr lines so non-streaming
		// providers still produce visible progress. Prefix with ProviderLabel
		// so users can tell which runner is talking when multiple are in flight.
		if p.Message != "" {
			prefix := s.arrow
			if p.ProviderLabel != "" {
				prefix = fmt.Sprintf("%s [%s]", s.arrow, p.ProviderLabel)
			}
			s.printLine(fmt.Sprintf("%s %s", prefix, p.Message))
		}
	case agent.PhaseDone:
		s.printLine(fmt.Sprintf(
			"%s Summary generated (%s, %s output tokens)",
			s.check, formatMs(p.DurationMs), formatTokenCount(p.OutputTokens)))
	}
}

