package claudecode

import (
	"bufio"
	"bytes"
	"errors"
	"os"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

func TestParseGenerateTextResponse_IsErrorEnvelope(t *testing.T) {
	t.Parallel()
	stdout := `{"type":"result","subtype":"success","is_error":true,"api_error_status":404,"result":"model not found"}`
	result, env, err := parseGenerateTextResponse([]byte(stdout))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if result != "model not found" {
		t.Errorf("result = %q; want %q", result, "model not found")
	}
	if env == nil {
		t.Fatal("envelope = nil; want non-nil")
	}
	if !env.IsError {
		t.Error("IsError = false; want true")
	}
	if env.APIErrorStatus == nil || *env.APIErrorStatus != 404 {
		t.Errorf("APIErrorStatus = %v; want *404", env.APIErrorStatus)
	}
}

func TestParseGenerateTextResponse_IsErrorEnvelopeNullResult(t *testing.T) {
	t.Parallel()
	// Claude CLI can emit is_error:true with result:null on internal failures.
	// The envelope's IsError / APIErrorStatus signal must survive even though
	// Result is absent — otherwise classification falls through to a generic
	// "missing result item" parse error and the upstream typed-error path
	// loses the api_error_status.
	//
	// Both wire shapes (single object and event array) must behave the same.
	tests := []struct {
		name   string
		stdout string
	}{
		{"single object", `{"type":"result","subtype":"error_during_execution","is_error":true,"api_error_status":500,"result":null}`},
		{"event array", `[{"type":"system"},{"type":"result","subtype":"error_during_execution","is_error":true,"api_error_status":500,"result":null}]`},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			result, env, err := parseGenerateTextResponse([]byte(tc.stdout))
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if result != "" {
				t.Errorf("result = %q; want empty string", result)
			}
			if env == nil {
				t.Fatal("envelope = nil; want non-nil")
			}
			if !env.IsError {
				t.Error("IsError = false; want true")
			}
			if env.APIErrorStatus == nil || *env.APIErrorStatus != 500 {
				t.Errorf("APIErrorStatus = %v; want *500", env.APIErrorStatus)
			}
		})
	}
}

func TestParseGenerateTextResponse(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		stdout  string
		want    string
		wantErr string
	}{
		{
			name:   "legacy object result",
			stdout: `{"result":"hello"}`,
			want:   "hello",
		},
		{
			name:   "legacy object empty result",
			stdout: `{"result":""}`,
			want:   "",
		},
		{
			name:   "array result",
			stdout: `[{"type":"system"},{"type":"result","result":"hello"}]`,
			want:   "hello",
		},
		{
			name:   "array empty result",
			stdout: `[{"type":"system"},{"type":"result","result":""}]`,
			want:   "",
		},
		{
			name:    "missing result item",
			stdout:  `[{"type":"system"},{"type":"assistant","message":"working"}]`,
			wantErr: "missing result item",
		},
		{
			name:    "invalid json",
			stdout:  `not json`,
			wantErr: "unsupported Claude CLI JSON response",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			got, _, err := parseGenerateTextResponse([]byte(tt.stdout))
			if tt.wantErr != "" {
				if err == nil {
					t.Fatal("expected error")
				}
				if !strings.Contains(err.Error(), tt.wantErr) {
					t.Fatalf("expected error containing %q, got %v", tt.wantErr, err)
				}
				return
			}

			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tt.want {
				t.Fatalf("parseGenerateTextResponse() = %q, want %q", got, tt.want)
			}
		})
	}
}

// replayHandler runs anthropicStreamHandler over an NDJSON body and returns
// the collected events + the terminal StreamResult. Shared across handler tests.
func replayHandler(t *testing.T, body []byte) ([]agent.GenerationProgress, *agent.StreamResult) {
	t.Helper()
	state := &agent.StreamState{}
	var events []agent.GenerationProgress
	var done *agent.StreamResult
	scanner := bufio.NewScanner(bytes.NewReader(body))
	scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		evs, terminal, err := anthropicStreamHandler(line, state)
		if err != nil {
			t.Fatalf("handler error = %v; want nil", err)
		}
		events = append(events, evs...)
		if terminal != nil {
			done = terminal
			break
		}
	}
	return events, done
}

func TestAnthropicStreamHandler_SuccessFixture(t *testing.T) {
	t.Parallel()
	raw, err := os.ReadFile("testdata/stream_success.jsonl")
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	events, done := replayHandler(t, raw)
	if done == nil {
		t.Fatal("done = nil; want terminal StreamResult with Text")
	}
	if done.Err != nil {
		t.Fatalf("done.Err = %v; want nil", done.Err)
	}
	if done.Text == "" {
		t.Error("done.Text is empty; want non-empty")
	}
	var sawConnect, sawFirst, sawGen bool
	for _, ev := range events {
		switch ev.Phase {
		case agent.PhaseConnecting:
			sawConnect = true
		case agent.PhaseFirstToken:
			sawFirst = true
		case agent.PhaseGenerating:
			sawGen = true
		}
	}
	if !sawConnect || !sawFirst || !sawGen {
		t.Errorf("missing phases: connecting=%v firstToken=%v generating=%v", sawConnect, sawFirst, sawGen)
	}
}

func TestAnthropicStreamHandler_ErrorFixture(t *testing.T) {
	t.Parallel()
	raw, err := os.ReadFile("testdata/stream_error_404.jsonl")
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	_, done := replayHandler(t, raw)
	if done == nil {
		t.Fatal("done = nil; want terminal StreamResult with Err")
	}
	var ae *agent.Error
	if !errors.As(done.Err, &ae) {
		t.Fatalf("done.Err = %v; want *agent.Error", done.Err)
	}
	if ae.APIStatus != 404 {
		t.Errorf("APIStatus = %d; want 404", ae.APIStatus)
	}
	if ae.Kind != agent.ErrorConfig {
		t.Errorf("Kind = %v; want %v (404 maps to Config)", ae.Kind, agent.ErrorConfig)
	}
	if ae.Provider != "Anthropic" {
		t.Errorf("Provider = %q; want Anthropic", ae.Provider)
	}
}

func TestAnthropicStreamHandler_MalformedLineSkipped(t *testing.T) {
	t.Parallel()
	// Malformed line in the middle of a stream should yield (nil,nil,nil) so
	// the runner keeps scanning and still sees the terminal result.
	body := strings.Join([]string{
		`{"type":"system","subtype":"init"}`,
		`not valid json`,
		`{"type":"result","subtype":"success","is_error":false,"result":"ok"}`,
	}, "\n")
	_, done := replayHandler(t, []byte(body))
	if done == nil || done.Text != "ok" {
		t.Errorf("done = %+v; want Text=ok", done)
	}
}

func TestClassifyClaudeEnvelope_StatusMapping(t *testing.T) {
	t.Parallel()
	cases := []struct {
		status int
		want   agent.ErrorKind
	}{
		{401, agent.ErrorAuth},
		{403, agent.ErrorAuth},
		{429, agent.ErrorRateLimit},
		{404, agent.ErrorConfig},
		{500, agent.ErrorUnknown},
	}
	for _, tc := range cases {
		got := classifyClaudeEnvelope("msg", &tc.status, 0)
		if got.Kind != tc.want {
			t.Errorf("status %d → Kind %v; want %v", tc.status, got.Kind, tc.want)
		}
		if got.Provider != "Anthropic" {
			t.Errorf("status %d: Provider = %q; want Anthropic", tc.status, got.Provider)
		}
	}
}

func TestClassifyClaudeEnvelope_AuthPhraseWithoutStatus(t *testing.T) {
	t.Parallel()
	got := classifyClaudeEnvelope("Invalid API key", nil, 1)
	if got.Kind != agent.ErrorAuth {
		t.Errorf("Kind = %v; want Auth (phrase fallback)", got.Kind)
	}
}

func TestClassifyClaudeStderr(t *testing.T) {
	t.Parallel()
	t.Run("auth phrase", func(t *testing.T) {
		t.Parallel()
		got := classifyClaudeStderr("Error: not logged in\n", 2)
		if got.Kind != agent.ErrorAuth {
			t.Errorf("Kind = %v; want Auth", got.Kind)
		}
	})
	t.Run("unknown falls through", func(t *testing.T) {
		t.Parallel()
		got := classifyClaudeStderr("generic crash trace", 137)
		if got.Kind != agent.ErrorUnknown {
			t.Errorf("Kind = %v; want Unknown", got.Kind)
		}
		if got.ExitCode != 137 {
			t.Errorf("ExitCode = %d; want 137", got.ExitCode)
		}
	})
	t.Run("truncates overlong messages", func(t *testing.T) {
		t.Parallel()
		long := strings.Repeat("x", stderrMessageMaxLen+100)
		got := classifyClaudeStderr(long, 1)
		if len(got.Message) != stderrMessageMaxLen {
			t.Errorf("Message len = %d; want %d", len(got.Message), stderrMessageMaxLen)
		}
	})
}

