	handler StreamLineHandler,
	progress ProgressFn,
) (string, error) {
	runner := cfg.Runner
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, cfg.Binary, cfg.Args...)
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())
	if cfg.Stdin != "" {
		cmd.Stdin = strings.NewReader(cfg.Stdin)
	}

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("%s: stdout pipe: %w", cfg.DisplayName, err)
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr

	if err := cmd.Start(); err != nil {
		return "", fmt.Errorf("%s: start: %w", cfg.DisplayName, err)
	}

	// closeStdout drains unread stdout then calls cmd.Wait exactly once, so
	// every exit path can call it without risking pipe-full deadlocks or
	// exec.ErrWaitAlreadyCalled.
	var (
		waitOnce sync.Once
		waitErr  error
	)
	closeStdout := func() {
		waitOnce.Do(func() {
			if _, drainErr := io.Copy(io.Discard, stdout); drainErr != nil {
				logging.Debug(ctx, "draining streaming stdout",
					slog.String("display", cfg.DisplayName),
					slog.String("error", drainErr.Error()))
			}
			waitErr = cmd.Wait()
		})
	}

	state := &StreamState{StartedAt: time.Now()}
	maxLine := cfg.MaxLineBytes
	if maxLine <= 0 {
		maxLine = defaultStreamMaxLineBytes
	}

	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), maxLine)

	emit := func(events []GenerationProgress) {
		if progress == nil {
			return
		}
		for _, ev := range events {
			ev.ProviderLabel = cfg.ProviderLabel
			progress(ev)
		}
	}

	var (
		done        *StreamResult
		handlerErr  error
		loopAborted bool
	)
	for scanner.Scan() {
		events, terminal, err := handler(scanner.Bytes(), state)
		emit(events)
		if err != nil {
			handlerErr = err
			loopAborted = true
			break
		}
		if terminal != nil {
			done = terminal
			loopAborted = true
			break
		}
	}
	scanErr := scanner.Err()
	if !loopAborted && scanErr != nil {
		handlerErr = scanErr
	}

	closeStdout()

	if done != nil && done.Err != nil {
		return "", done.Err
	}
	if handlerErr != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		return "", fmt.Errorf("%s: %w", cfg.DisplayName, handlerErr)
	}
	if done != nil && done.Text != "" {
		durationMs := done.DurationMs
		if durationMs == 0 {
			durationMs = int(time.Since(state.StartedAt) / time.Millisecond)
		}
		if progress != nil {
			progress(GenerationProgress{
				Phase:         PhaseDone,
				OutputTokens:  done.OutputTokens,
				DurationMs:    durationMs,
				ProviderLabel: cfg.ProviderLabel,
			})
		}
		return done.Text, nil
	}
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return "", context.DeadlineExceeded
	}
	if errors.Is(ctx.Err(), context.Canceled) {
		return "", context.Canceled
	}
	if waitErr == nil {
		return "", fmt.Errorf("%s: stream exited without result", cfg.DisplayName)
	}
	if cfg.FallbackDetect != nil && cfg.LegacyFallback != nil && cfg.FallbackDetect(stderr.String()) {
		return cfg.LegacyFallback(ctx)
	}
	detail := strings.TrimSpace(stderr.String())
	if detail == "" {
		return "", fmt.Errorf("%s: %w", cfg.DisplayName, waitErr)
	}
	return "", fmt.Errorf("%s: %s: %w", cfg.DisplayName, detail, waitErr)
