func printfRunner(payload, stderrOut string, exitCode int) TextCommandRunner {
	return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		script := "printf '%s\\n' " + shellQuote(payload)
		if stderrOut != "" {
			script += fmt.Sprintf("; printf '%%s\\n' %s >&2", shellQuote(stderrOut))
		}
		if exitCode != 0 {
			script += fmt.Sprintf("; exit %d", exitCode)
		}
		return exec.CommandContext(ctx, "sh", "-c", script)
	}
}

// shellQuote single-quotes a string for safe embedding in a POSIX shell
// command. Used by tests only — replaces each embedded single quote with the
// standard '\” escape sequence.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

