297		// Emit terminal line, then ~80 KB of trailing garbage. If RunStreamingCLI
298		// breaks out of the loop without draining stdout, cmd.Wait() blocks on a
299		// full pipe and the test times out.
300		var trailer strings.Builder
301		for range 800 {
302			trailer.WriteString(strings.Repeat("x", 99))
303			trailer.WriteByte('\n')
304		}
