308		handler := func(line []byte, _ *StreamState) ([]GenerationProgress, *StreamResult, error) {
309			if bytes.Equal(line, []byte("DONE")) {
310				return nil, &StreamResult{Text: "ok"}, nil
311			}
312			return nil, nil, nil
313		}
314	
315		done := make(chan struct{})
316		var (
317			text string
318			err  error
319		)
320		go func() {
321			defer close(done)
322			cfg := StreamConfig{Runner: runner, Binary: "sh", DisplayName: "test-cli"}
323			text, err = RunStreamingCLI(context.Background(), cfg, handler, nil)
324		}()
