func TestRunStreamingCLI_ContextCanceledMidStream(t *testing.T) {
	t.Parallel()

	if runtime.GOOS == windowsOS {
		t.Skip("uses POSIX shell command")
	}

	// Subprocess sleeps so the scanner blocks and ctx cancel propagates.
	runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		return exec.CommandContext(ctx, "sh", "-c", "sleep 10")
	}

	ctx, cancel := context.WithCancel(context.Background())
	go func() {
		time.Sleep(10 * time.Millisecond)
		cancel()
	}()

	handler := func(_ []byte, _ *StreamState) ([]GenerationProgress, *StreamResult, error) {
		return nil, nil, nil
	}

	cfg := StreamConfig{Runner: runner, Binary: "sh", DisplayName: "test-cli"}
	_, err := RunStreamingCLI(ctx, cfg, handler, nil)
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("err = %v, want context.Canceled", err)
	}
}

func TestRunStreamingCLI_StdoutDrainAfterTerminal(t *testing.T) {
	t.Parallel()

	if runtime.GOOS == windowsOS {
		t.Skip("uses POSIX shell command")
	}

	// Emit terminal line, then ~80 KB of trailing garbage. If RunStreamingCLI
	// breaks out of the loop without draining stdout, cmd.Wait() blocks on a
	// full pipe and the test times out.
	var trailer strings.Builder
	for range 800 {
		trailer.WriteString(strings.Repeat("x", 99))
		trailer.WriteByte('\n')
	}
	payload := "DONE\n" + trailer.String()
	runner := printfRunner(strings.TrimRight(payload, "\n"), "", 0)

	handler := func(line []byte, _ *StreamState) ([]GenerationProgress, *StreamResult, error) {
		if bytes.Equal(line, []byte("DONE")) {
			return nil, &StreamResult{Text: "ok"}, nil
		}
		return nil, nil, nil
	}

	done := make(chan struct{})
	var (
		text string
		err  error
	)
	go func() {
		defer close(done)
		cfg := StreamConfig{Runner: runner, Binary: "sh", DisplayName: "test-cli"}
		text, err = RunStreamingCLI(context.Background(), cfg, handler, nil)
	}()

	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("RunStreamingCLI deadlocked on undrained stdout")
	}
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if text != "ok" {
		t.Fatalf("text = %q, want %q", text, "ok")
	}
}

func TestRunStreamingCLI_MalformedLineSkipped(t *testing.T) {
	t.Parallel()

	if runtime.GOOS == windowsOS {
		t.Skip("uses POSIX shell command")
	}

	// Uses octal \033 (not \x1b) for POSIX-portable escape bytes.
	payload := "\033[31mGARBAGE\033[0m\nGOOD\nDONE:final"
	runner := printfRunner(payload, "", 0)

	var scanned int
	handler := func(line []byte, _ *StreamState) ([]GenerationProgress, *StreamResult, error) {
		scanned++
		switch {
		case bytes.Contains(line, []byte("GARBAGE")):
			// Skip: simulate a malformed/unparseable line.
			return nil, nil, nil
		case bytes.Equal(line, []byte("GOOD")):
			return []GenerationProgress{{Phase: PhaseGenerating, OutputTokens: 7}}, nil, nil
		case bytes.HasPrefix(line, []byte("DONE:")):
			return nil, &StreamResult{Text: "final"}, nil
		}
		return nil, nil, nil
	}

	var seen []GenerationProgress
	progress := func(p GenerationProgress) { seen = append(seen, p) }

	cfg := StreamConfig{Runner: runner, Binary: "sh", DisplayName: "test-cli", ProviderLabel: "p"}
	text, err := RunStreamingCLI(context.Background(), cfg, handler, progress)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if text != "final" {
		t.Fatalf("text = %q, want %q", text, "final")
	}
	if scanned != 3 {
		t.Fatalf("handler saw %d lines, want 3 (malformed, good, done)", scanned)
	}
	// Expect one generating event + one synthesized done.
	if len(seen) != 2 || seen[0].Phase != PhaseGenerating || seen[1].Phase != PhaseDone {
		t.Fatalf("events = %+v, want [generating, done]", seen)
	}
}

