		t.Fatalf("text = %q, want %q", text, "final")
	}

	// Expect: PhaseConnecting + 3 PhaseMessage + PhaseDone = 5 events.
	if len(events) != len(lines)+2 {
		t.Fatalf("events = %d, want %d: %+v", len(events), len(lines)+2, events)
	}
	if events[0].Phase != PhaseConnecting {
		t.Errorf("event[0].Phase = %q, want connecting", events[0].Phase)
	}
	for i, want := range lines {
		got := events[i+1]
		if got.Phase != PhaseMessage {
			t.Errorf("event[%d].Phase = %q, want message", i+1, got.Phase)
		}
		if got.Message != want {
			t.Errorf("event[%d].Message = %q, want %q", i+1, got.Message, want)
		}
	}
	if events[len(events)-1].Phase != PhaseDone {
		t.Errorf("last event phase = %q, want done", events[len(events)-1].Phase)
	}
}

